"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { createNewTask } from "@/app/actions/task-actions";

export default function TaskFormModal({ isOpen, onClose }: any) {
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    const formData = new FormData(e.currentTarget);
    
    const res = await createNewTask({
      title: formData.get("title") as string,
      description: formData.get("description") as string,
      content: formData.get("content") as string,
      sprint: formData.get("sprint") as string,
    });

    if (res.success) onClose();
    setLoading(false);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent>
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Nieuwe Taak Toevoegen</DialogTitle>
            <DialogDescription>Voeg documentatie toe aan je scrum bord.</DialogDescription>
          </DialogHeader>
          
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="title">Titel</Label>
              <Input id="title" name="title" placeholder="Taak naam" required />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="sprint">Sprint</Label>
              <Input id="sprint" name="sprint" placeholder="Bijv: Sprint 1" />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="description">Korte Beschrijving</Label>
              <Input id="description" name="description" placeholder="Wat ga je doen?" />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="content">Documentatie (Content)</Label>
              <Textarea id="content" name="content" className="h-32" placeholder="JSON veya detaylı açıklama..." />
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>Annuleren</Button>
            <Button type="submit" disabled={loading} className="bg-blue-600 text-white">
              {loading ? "Opslaan..." : "Toevoegen"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}